; ==============================================================
; Bank 6 ($06)  file offset $018000-$01BFFF
; OVERWORLD / FIELD OBJECT MANAGER
;   Manages on-field sprites/NPCs: iterates an object table at
;   WRAM[$D7D2] (32-byte entries, $FF = end/inactive sentinel),
;   dispatches each active object through a 16-type handler
;   table via RST $00.
;
; Key WRAM addresses observed:
;   $C8EB      - flag byte: bits 1,3,4,7 guard fn2; bit 2 extra check
;   $C91E      - extra state flag checked in fn2
;   $D7D2+     - object table (32-byte entries, up to ~64 objects)
;   $D8D7      - object state flag used in fn3 dispatch
;   $C8A6      - another per-frame state flag
;   HRAM $FFD5:FFD6 - scratch for current object screen position
;
; Key WRAM addresses (additional):
;   $C88F      - transition/fade lock (fn6 guard)
;   $C8EC      - global busy lock (fn1 guard)
;   $C8EF      - sub-mode counter (fn1 guard when bit4 set)
;   $C969      - extra state (fn1 guard for bit2 path)
;   $CAC0      - player object index (fn5)
;   $CB0C      - object coordinate table (fn5 via $260A)
;   $D7BE      - secondary object list, 6 entries (fn4)
;   $D9F8:D9F9 - tilemap source pointer used by bank80 fn5 (shared)
;
; 7 functions via RST $10:
;   fn0   → $4B1F  object-flag reset: clear per-frame "on-screen" bits,
;                    latch scroll regs $FF92/$FF93/$FF95 → WRAM $FFDB
;   fn1   → $4CBC  field-object OAM/SPRITE render pass (walks $D7D2, builds sprites;
;                  render counterpart to fn3; bank1 calls it right after fn6)
;   fn2   → $400F  GUARDED field-object update (per-frame; skips if overlay active)
;   fn3   → $4028  field-object UPDATE/ANIMATION pass over $D7D2 (unguarded; the
;                  init call from bank1 $40A1 uses this to force frame-0 placement)
;   fn4   → $4D5A  field-object SPRITE-TILE loader: LZ-decompress each $D7BE
;                  object's sprite gfx into VRAM via SafeTileLoad (6 entries)
;   fn5   → $4F9A  collision/interaction scan (player vs objects)
;   fn6   → $6034  field mode router: dispatch to sub-screen by $C8EB bits
; RST $00 at $0000: state-dispatch (A=index, DW table follows instruction)
; ==============================================================
SECTION "bank6",ROMX[$400F],BANK[$06]


; ============================================================================
; Bank6_fn2 ($400F) — GUARDED entry to the field-object update pass.
;   The per-frame wrapper around fn3: skips the whole object update when a
;   full-screen overlay owns the frame — RET if any of $C8EB bits 1(party),
;   3(zone-select/mini-map), 4(battle), 7(battle-view) is set, or bit2(zone
;   scroll) set AND $C91E==1 (mid-transition). Otherwise falls through to fn3.
;   (Called per-frame by bank1 $4EEE. Cf. fn3, which init calls unguarded.)
; ============================================================================
Bank6_fn2:  ; $400F
    LD A,($C8EB)                           ; $400F [FA EB C8]  ; wStateFlags
    BIT 1,A                                ; $4012 [CB 4F]      ; party screen?
    RET NZ                                 ; $4014 [C0]
    BIT 3,A                                ; $4015 [CB 5F]      ; zone-select / mini-map?
    RET NZ                                 ; $4017 [C0]
    BIT 4,A                                ; $4018 [CB 67]      ; battle scene?
    RET NZ                                 ; $401A [C0]
    BIT 7,A                                ; $401B [CB 7F]      ; battle view?
    RET NZ                                 ; $401D [C0]
    BIT 2,A                                ; $401E [CB 57]      ; zone-scroll transition?
    JR Z,$4028                             ; $4020 [28 06]      ; not scrolling -> update objects
    LD A,($C91E)                           ; $4022 [FA 1E C9]  ; wAreaMode (transition phase)
    CP $01                                 ; $4025 [FE 01]
    RET Z                                  ; $4027 [C8]         ; mid-transition -> skip this frame

; ============================================================================
; Bank6_fn3 ($4028) — FIELD-OBJECT UPDATE / ANIMATION PASS.
; ----------------------------------------------------------------------------
; Walks the live object table at WRAM $D7D2 (32-byte records) and steps each
; active object's animation/movement. For every record:
;   byte[0] = $FF  -> end of table, return.
;   byte[1] = $FF  -> inactive slot, skip.
;   else           -> Sub_4043: cache the record ptr in hObjPtr ($FFD5:D6), skip
;                     if byte[0] bit6 set (paused/interacted), else dispatch on
;                     the low nibble of byte[0] = object TYPE (0-15) via RST $00.
; The per-type handlers ($4070..) advance the object using two throttles read
; from the frame counter: $D8D7 (player move in progress) and $C8A6 & 7 (every
; 8th frame), so NPCs animate/step in lock-step with the walk cadence.
;
; TWO ENTRIES: fn2 ($400F) is the GUARDED per-frame call (bank1 $4EEE). fn3
; ($4028) is the UNGUARDED force-update, called ONCE at bank1 init ($40A1) with
; $C8A6 temporarily = 0 — that makes the "every-8-frames" gate pass on frame 0,
; forcing every object to its initial (frame-0) sprite/position placement.
; ============================================================================
Bank6_fn3:  ; $4028
    LD HL,$D7D2                            ; $4028 [21 D2 D7]  ; HL → first object entry
.lbl_402B:
    LD A,(HL)                              ; $402B [7E]        ; byte[0] = object type/flags
    CP $FF                                 ; $402C [FE FF]
    RET Z                                  ; $402E [C8]         ; $FF → end of object list
    INC HL                                 ; $402F [23]
    LD A,(HL)                              ; $4030 [7E]        ; byte[1] = active flag
    DEC HL                                 ; $4031 [2B]
    CP $FF                                 ; $4032 [FE FF]
    PUSH HL                                ; $4034 [E5]
    CALL NZ,$4043                          ; $4035 [C4 43 40]  ; byte[1]≠$FF → update this object
    POP HL                                 ; $4038 [E1]
    LD A,L                                 ; $4039 [7D]        ; advance HL to next entry (+32)
    ADD A,$20                              ; $403A [C6 20]
    LD L,A                                 ; $403C [6F]
    LD A,H                                 ; $403D [7C]
    ADC A,$00                              ; $403E [CE 00]
    LD H,A                                 ; $4040 [67]
    JR,$402B                               ; $4041 [18 E8]     ; loop to next object
; ----------------------------------------------------------------------------
; Sub_4043 — update ONE object.  HL → its 32-byte record in $D7D2.
;   Record byte[0] = type/flags (bit6 = paused/interacted, low nibble = type);
;   byte[+5] = per-object state byte (also has a bit6 "static" flag, see $4070).
; ----------------------------------------------------------------------------
.lbl_4043:
    LD A,L                                 ; $4043 [7D]
    LDH ($FFD5),A                          ; $4044 [E0 D5]  ; hObjPtr.lo = record ptr lo
    LD A,H                                 ; $4046 [7C]
    LDH ($FFD6),A                          ; $4047 [E0 D6]  ; hObjPtr.hi = record ptr hi
    LD A,(HL)                              ; $4049 [7E]     ; A = byte[0] of THIS $D7D2 record (HL = $D7D2 + n*$20)
    BIT 6,A                                ; $404A [CB 77]
    RET NZ                                 ; $404C [C0]      ; bit6 set → paused/interacted, don't animate
    AND $0F                                ; $404D [E6 0F]  ; low nibble of that byte = object TYPE (0-15)
    RST $00                                ; $404F [C7]  ; dispatch on TYPE (value comes from $D7D2 byte[0]) → table below
    ; RST $00 table (16 object-type handlers), indexed by $D7D2 byte[0] & $0F.
    ; NOTE: only the handler MECHANISMS are traced; per-type behavior labels marked
    ; "(inf)" are INFERRED from offsets/calls (see each handler's header), not verified.
    DW $4070    ; $4050 [70 40]  type 0  — idle, stepped with player walk (traced)
    DW $4090    ; $4052 [90 40]  type 1  — idle + ambient anim on +6 (traced)
    DW $40B1    ; $4054 [B1 40]  type 2  — autonomous mover (traced); patrol shape (inf)
    DW $4122    ; $4056 [22 41]  type 3  — autonomous mover, 4-phase dir (traced); pattern (inf)
    DW $41A5    ; $4058 [A5 41]  type 4  — autonomous mover; pattern (inf)
    DW $4266    ; $405A [66 42]  type 5  — autonomous mover; pattern (inf)
    DW $42D7    ; $405C [D7 42]  type 6  — player-synced (via $4A83) (traced)
    DW $4309    ; $405E [09 43]  type 7  — player-synced + anim (traced)
    DW $433F    ; $4060 [3F 43]  type 8  — autonomous mover; pattern (inf)
    DW $43B0    ; $4062 [B0 43]  type 9  — autonomous mover; pattern (inf)
    DW $441F    ; $4064 [1F 44]  type 10 — autonomous mover, edge-aware? (inf)
    DW $4070    ; $4066 [70 40]  type 11 — (aliases type 0 idle)
    DW $4070    ; $4068 [70 40]  type 12 — (aliases type 0 idle)
    DW $4070    ; $406A [70 40]  type 13 — (aliases type 0 idle)
    DW $44C5    ; $406C [C5 44]  type 14 — complex/scripted actor; identity (inf)
    DW $4691    ; $406E [91 46]  type 15 — small mover/trigger; role (inf)
; ----------------------------------------------------------------------------
; OBJECT RECORD LAYOUT (32 bytes, base = hObjPtr $FFD5:D6) — used by all handlers:
;   +0  type/flags  (bit6 = paused/interacted, low nibble = TYPE 0-15)
;   +1  active flag ($FF = empty slot)
;   +2  X screen/tile position  (compared <<4 for sub-pixel alignment)
;   +3  Y screen/tile position
;   +5  state        (bit0 = moving, bit6 = face-locked, bit7 = static)
;   +6  anim frame / facing index (0-3; drives the OAM tile via $4A83/$4AA1)
;   +7  move timer   (counts down each step; reloaded to $10 on a new cell step)
;   +8  direction phase (picks the per-type move vector)
;   +$11 OAM sprite tile written by the tail routines
;   +$18/+$19  X sub-pixel accumulator ;  +$1A/+$1B  Y sub-pixel accumulator
;
; HANDLER FAMILIES (dispatched by TYPE above):
;   idle          : t0/B/C/D ($4070), t1 ($4090 = idle + ambient anim on +6)
;   autonomous move: t2,t3,t4,t5,t8,t9,tA — pick a direction, SET +5 bit0, walk a
;                    cell via the sub-pixel stepper $49BA (each has its own small
;                    "direction -> BC/DE vector" helper).
;   player-synced  : t6 ($42D7), t7 ($4309) — move/turn in lock-step with the
;                    player via $4A83 (no free roaming).
;   complex/scripted: tE ($44C5, the largest) ;  misc trigger: tF ($4691).
; Shared tails: $4A48 finish-step & place · $4A83 sync frame to player walk ·
;   $4AA1 idle-anim frame · $49BA/$4A01 sub-pixel X/Y stepper.
; ----------------------------------------------------------------------------
; --- type 0 / B / C / D handler: idle NPC, stepped in time with player walk ---
.lbl_4070:
    LDH A,($FFD5)                          ; $4070 [F0 D5]  ; HL = record + 5 (state byte):
    ADD A,$05                              ; $4072 [C6 05]
    LD L,A                                 ; $4074 [6F]
    LDH A,($FFD6)                          ; $4075 [F0 D6]
    ADC A,$00                              ; $4077 [CE 00]
    LD H,A                                 ; $4079 [67]
    BIT 6,(HL)                             ; $407A [CB 76]      ; state bit6 = "static" (no motion)?
    JR NZ,$408D                            ; $407C [20 0F]      ; static → just redraw ($4A48)
    LD A,($D8D7)                           ; $407E [FA D7 D8]  ; wSaveMode: player move in progress?
.lbl_4081:
    OR A                                   ; $4081 [B7]
    JP NZ,$4A83                            ; $4082 [C2 83 4A]  ; yes → step this NPC in sync ($4A83)
    LD A,($C8A6)                           ; $4085 [FA A6 C8]  ; wFrameCounter.lo
    AND $07                                ; $4088 [E6 07]      ; every-8-frames throttle
    JP NZ,$4AA1                            ; $408A [C2 A1 4A]  ; off-beat frame → idle-tick ($4AA1)
.lbl_408D:                                 ;                    ; (init call zeroes $C8A6 → gate passes)
    JP $4A48                               ; $408D [C3 48 4A]  ; on-beat / static → place+redraw ($4A48)
; --- type 1: idle NPC + ambient animation (cycles +6 through 0-3 every 16 frames) ---
.lbl_4090:
    LD A,($C8A6)                           ; $4090 [FA A6 C8]  ; WRAM[$C8A6]
    AND $07                                ; $4093 [E6 07]
    JP NZ,$4AA1                            ; $4095 [C2 A1 4A]
    LD A,($C8A6)                           ; $4098 [FA A6 C8]  ; WRAM[$C8A6]
    AND $0F                                ; $409B [E6 0F]
    JR NZ,$40AE                            ; $409D [20 0F]
    LDH A,($FFD5)                          ; $409F [F0 D5]  ; HRAM[$FFD5]
    ADD A,$06                              ; $40A1 [C6 06]
    LD L,A                                 ; $40A3 [6F]
    LDH A,($FFD6)                          ; $40A4 [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $40A6 [CE 00]
    LD H,A                                 ; $40A8 [67]
    LD A,(HL)                              ; $40A9 [7E]
    INC A                                  ; $40AA [3C]
    AND $03                                ; $40AB [E6 03]
    LD (HL),A                              ; $40AD [77]
.lbl_40AE:
    JP $4A48                               ; $40AE [C3 48 4A]
; --- type 2: autonomous mover. PROVEN: throttle &$01; when +7 idle, derive a dir from
;     +8, SET +5 bit0 (moving), get a target vector from $4100 (phase0 +1/+$20, phase1
;     -1/-$20), and step via $49BA until BC-DE==0. Calling it a 2-way horizontal patrol
;     is an INFERENCE from those vectors — not confirmed. ---
.lbl_40B1:
    LD A,($C8A6)                           ; $40B1 [FA A6 C8]  ; WRAM[$C8A6]
    AND $01                                ; $40B4 [E6 01]
    JP NZ,$4AA1                            ; $40B6 [C2 A1 4A]
    LDH A,($FFD5)                          ; $40B9 [F0 D5]  ; HRAM[$FFD5]
    ADD A,$07                              ; $40BB [C6 07]
    LD L,A                                 ; $40BD [6F]
    LDH A,($FFD6)                          ; $40BE [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $40C0 [CE 00]
    LD H,A                                 ; $40C2 [67]
    LDI A,(HL)                             ; $40C3 [2A]
    OR A                                   ; $40C4 [B7]
    JP NZ,$40FD                            ; $40C5 [C2 FD 40]
    LDD A,(HL)                             ; $40C8 [3A]
    AND $01                                ; $40C9 [E6 01]
    XOR $01                                ; $40CB [EE 01]
    ADD A,A                                ; $40CD [87]
    INC A                                  ; $40CE [3C]
    DEC HL                                 ; $40CF [2B]
    LDD (HL),A                             ; $40D0 [32]
    BIT 6,(HL)                             ; $40D1 [CB 76]
    JP NZ,$40FD                            ; $40D3 [C2 FD 40]
    LD A,($D8D7)                           ; $40D6 [FA D7 D8]  ; WRAM[$D8D7]
    OR A                                   ; $40D9 [B7]
    JP NZ,$40FD                            ; $40DA [C2 FD 40]
    SET 0,(HL)                             ; $40DD [CB C6]
    CALL $4100                             ; $40DF [CD 00 41]
    LD A,C                                 ; $40E2 [79]
    SUB E                                  ; $40E3 [93]
    LD C,A                                 ; $40E4 [4F]
    LD A,B                                 ; $40E5 [78]
    SBC A,D                                ; $40E6 [9A]
    LD B,A                                 ; $40E7 [47]
    LD A,C                                 ; $40E8 [79]
    OR B                                   ; $40E9 [B0]
    JR NZ,$40FD                            ; $40EA [20 11]
    LDH A,($FFD5)                          ; $40EC [F0 D5]  ; HRAM[$FFD5]
    ADD A,$08                              ; $40EE [C6 08]
    LD L,A                                 ; $40F0 [6F]
    LDH A,($FFD6)                          ; $40F1 [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $40F3 [CE 00]
    LD H,A                                 ; $40F5 [67]
    LD A,(HL)                              ; $40F6 [7E]
    INC A                                  ; $40F7 [3C]
    AND $01                                ; $40F8 [E6 01]
    LDI (HL),A                             ; $40FA [22]
    LD (HL),$10                            ; $40FB [36 10]
.lbl_40FD:
    JP $4A48                               ; $40FD [C3 48 4A]
; --- Sub_4100: type-2 direction->vector. Reads +8 phase, RST$00 picks BC/DE:
;     phase0 = +1 / +$20 (right/down), phase1 = -1 / -$20 (left/up); feeds $49BA. ---
.lbl_4100:
    LDH A,($FFD5)                          ; $4100 [F0 D5]  ; HRAM[$FFD5]
    ADD A,$08                              ; $4102 [C6 08]
    LD L,A                                 ; $4104 [6F]
    LDH A,($FFD6)                          ; $4105 [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $4107 [CE 00]
    LD H,A                                 ; $4109 [67]
    LD A,(HL)                              ; $410A [7E]
    RST $00                                ; $410B [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (2 states):
    DW $4110    ; $410C [10 41]  state 0
    DW $4119    ; $410E [19 41]  state 1
.lbl_4110:
    LD BC,$0001                            ; $4110 [01 01 00]
    LD DE,$0020                            ; $4113 [11 20 00]
    JP $49BA                               ; $4116 [C3 BA 49]
.lbl_4119:
    LD BC,$FFFF                            ; $4119 [01 FF FF]
    LD DE,$FFE0                            ; $411C [11 E0 FF]
    JP $49BA                               ; $411F [C3 BA 49]
; --- type 3: autonomous mover. PROVEN: dir from +8 masked &$03, vector via $416D,
;     steps both X ($49BA) and Y ($4A01); same skeleton as type 2. "4-direction" is
;     INFERRED from the &$03 mask (4 phases) — the actual pattern isn't traced. ---
.lbl_4122:
    LD A,($C8A6)                           ; $4122 [FA A6 C8]  ; WRAM[$C8A6]
    AND $01                                ; $4125 [E6 01]
    JP NZ,$4AA1                            ; $4127 [C2 A1 4A]
    LDH A,($FFD5)                          ; $412A [F0 D5]  ; HRAM[$FFD5]
    ADD A,$07                              ; $412C [C6 07]
    LD L,A                                 ; $412E [6F]
    LDH A,($FFD6)                          ; $412F [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $4131 [CE 00]
    LD H,A                                 ; $4133 [67]
    LDI A,(HL)                             ; $4134 [2A]
    OR A                                   ; $4135 [B7]
    JP NZ,$416A                            ; $4136 [C2 6A 41]
    LDD A,(HL)                             ; $4139 [3A]
    AND $03                                ; $413A [E6 03]
    DEC HL                                 ; $413C [2B]
    LDD (HL),A                             ; $413D [32]
    BIT 6,(HL)                             ; $413E [CB 76]
    JP NZ,$416A                            ; $4140 [C2 6A 41]
    LD A,($D8D7)                           ; $4143 [FA D7 D8]  ; WRAM[$D8D7]
    OR A                                   ; $4146 [B7]
    JP NZ,$416A                            ; $4147 [C2 6A 41]
    SET 0,(HL)                             ; $414A [CB C6]
    CALL $416D                             ; $414C [CD 6D 41]
    LD A,C                                 ; $414F [79]
    SUB E                                  ; $4150 [93]
    LD C,A                                 ; $4151 [4F]
    LD A,B                                 ; $4152 [78]
    SBC A,D                                ; $4153 [9A]
    LD B,A                                 ; $4154 [47]
    LD A,C                                 ; $4155 [79]
    OR B                                   ; $4156 [B0]
    JR NZ,$416A                            ; $4157 [20 11]
    LDH A,($FFD5)                          ; $4159 [F0 D5]  ; HRAM[$FFD5]
    ADD A,$08                              ; $415B [C6 08]
    LD L,A                                 ; $415D [6F]
    LDH A,($FFD6)                          ; $415E [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $4160 [CE 00]
    LD H,A                                 ; $4162 [67]
    LD A,(HL)                              ; $4163 [7E]
    DEC A                                  ; $4164 [3D]
    AND $03                                ; $4165 [E6 03]
    LDI (HL),A                             ; $4167 [22]
    LD (HL),$10                            ; $4168 [36 10]
.lbl_416A:
    JP $4A48                               ; $416A [C3 48 4A]
; --- Sub_416D: type-3 direction->vector (4-way version of $4100; feeds $49BA/$4A01). ---
.lbl_416D:
    LDH A,($FFD5)                          ; $416D [F0 D5]  ; HRAM[$FFD5]
    ADD A,$08                              ; $416F [C6 08]
    LD L,A                                 ; $4171 [6F]
    LDH A,($FFD6)                          ; $4172 [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $4174 [CE 00]
    LD H,A                                 ; $4176 [67]
    LD A,(HL)                              ; $4177 [7E]
    RST $00                                ; $4178 [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (4 states):
    DW $4181    ; $4179 [81 41]  state 0
    DW $418A    ; $417B [8A 41]  state 1
    DW $4193    ; $417D [93 41]  state 2
    DW $419C    ; $417F [9C 41]  state 3
.lbl_4181:
    LD BC,$0001                            ; $4181 [01 01 00]
    LD DE,$0020                            ; $4184 [11 20 00]
    JP $4A01                               ; $4187 [C3 01 4A]
.lbl_418A:
    LD BC,$FFFF                            ; $418A [01 FF FF]
    LD DE,$0000                            ; $418D [11 00 00]
    JP $49BA                               ; $4190 [C3 BA 49]
.lbl_4193:
    LD BC,$FFFF                            ; $4193 [01 FF FF]
    LD DE,$0000                            ; $4196 [11 00 00]
    JP $4A01                               ; $4199 [C3 01 4A]
.lbl_419C:
    LD BC,$0001                            ; $419C [01 01 00]
    LD DE,$0020                            ; $419F [11 20 00]
    JP $49BA                               ; $41A2 [C3 BA 49]
; --- type 4: autonomous mover. Move MECHANISM proven (SET +5 bit0; vector via $41F7;
;     steps X/Y through $49BA/$4A01). PATTERN INFERRED (not traced): the specific
;     movement rule differs from t2/t3 but which rule (random walk / path?) is unverified. ---
.lbl_41A5:
    LD A,($C8A6)                           ; $41A5 [FA A6 C8]  ; WRAM[$C8A6]
    AND $01                                ; $41A8 [E6 01]
    JP NZ,$4AA1                            ; $41AA [C2 A1 4A]
    LDH A,($FFD5)                          ; $41AD [F0 D5]  ; HRAM[$FFD5]
    ADD A,$07                              ; $41AF [C6 07]
    LD L,A                                 ; $41B1 [6F]
    LDH A,($FFD6)                          ; $41B2 [F0 D6]  ; HRAM[$FFD6]
    ADC A,$00                              ; $41B4 [CE 00]
    LD H,A                                 ; $41B6 [67]
    LDI A,(HL)                             ; $41B7 [2A]
    OR A                                   ; $41B8 [B7]
    JP NZ,$41F7                            ; $41B9 [C2 F7 41]
    LDD A,(HL)                             ; $41BC [3A]
    AND $07                                ; $41BD [E6 07]
    LD DE,$425E                            ; $41BF [11 5E 42]
    ADD A,E                                ; $41C2 [83]
    LD E,A                                 ; $41C3 [5F]
    LD A,$00                               ; $41C4 [3E 00]
    ADC A,D                                ; $41C6 [8A]
    LD D,A                                 ; $41C7 [57]
    LD A,(DE)                              ; $41C8 [1A]
    DEC HL                                 ; $41C9 [2B]
    LDD (HL),A                             ; $41CA [32]
    BIT 6,(HL)                             ; $41CB [CB 76]
    JP NZ,$41F7                            ; $41CD [C2 F7 41]
