; Object visibility reset:
;   Clears bit 5 of HRAM[$FF90], then walks object table at WRAM[$D7D2]
;   (stride 32 bytes, $FF sentinel) clearing bit 5 at byte[5] of each entry
;   (the "on-screen" or "moved-this-frame" flag). After the loop, guards on
;   WRAM[$D8D7]; if clear, latches HRAM scroll regs $FF92/$FF93/$FF95 into
;   WRAM[$FFDB:FFDC:FFDD] for the next frame.
