    LD E,A                                 ; $4BFC [5F]
    LDI A,(HL)                             ; $4BFD [2A]
    LD D,A                                 ; $4BFE [57]
    LDI A,(HL)                             ; $4BFF [2A]
    LD H,(HL)                              ; $4C00 [66]
    LD L,A                                 ; $4C01 [6F]
    LD A,E                                 ; $4C02 [7B]
