    PUSH DE                                ; $4C18 [D5]
    LD A,E                                 ; $4C19 [7B]
    ADD A,$08                              ; $4C1A [C6 08]
    LD E,A                                 ; $4C1C [5F]
    LD A,D                                 ; $4C1D [7A]
    ADC A,$00                              ; $4C1E [CE 00]
    LD D,A                                 ; $4C20 [57]
    CALL $4C72                             ; $4C21 [CD 72 4C]
    POP DE                                 ; $4C24 [D1]
    POP HL                                 ; $4C25 [E1]
    JR Z,$4C55                             ; $4C26 [28 2D]
