    LD D,A                                 ; $4C2F [57]
    CALL $4C72                             ; $4C30 [CD 72 4C]
    JR NZ,$4C6E                            ; $4C33 [20 39]
    JR,$4C55                               ; $4C35 [18 1E]
.lbl_4C37:
