    ADD A,$08                              ; $4C3A [C6 08]
    LD L,A                                 ; $4C3C [6F]
    LD A,H                                 ; $4C3D [7C]
    ADC A,$00                              ; $4C3E [CE 00]
    LD H,A                                 ; $4C40 [67]
