    POP DE                                 ; $4C44 [D1]
    POP HL                                 ; $4C45 [E1]
    JR Z,$4C55                             ; $4C46 [28 0D]
    LD A,L                                 ; $4C48 [7D]
    ADD A,$F8                              ; $4C49 [C6 F8]
