    LD D,A                                 ; $4C79 [57]
    LD A,E                                 ; $4C7A [7B]
    AND $0F                                ; $4C7B [E6 0F]
    OR D                                   ; $4C7D [B2]
    LD B,A                                 ; $4C7E [47]
    LDH A,($FFD5)                          ; $4C7F [F0 D5]  ; HRAM[$FFD5]
    CP B                                   ; $4C81 [B8]
