    ADD HL,HL                              ; $4CA0 [29]
    LD A,L                                 ; $4CA1 [7D]
    ADD A,$73                              ; $4CA2 [C6 73]
    LD L,A                                 ; $4CA4 [6F]
    LD A,H                                 ; $4CA5 [7C]
    ADC A,$C9                              ; $4CA6 [CE C9]
