; ============================================================================
; Bank6_fn1 ($4CBC) — FIELD-OBJECT OAM / SPRITE RENDER PASS.
; ----------------------------------------------------------------------------
; The RENDER counterpart to fn3: same $D7D2 walk + same skip rules, but instead
; of updating object state it emits each active object's SPRITE to OAM. bank1's
; per-frame loop calls fn6 (update/route) then fn1 ($4E15) so movement computed
; this frame is drawn immediately after.
; GUARD (skip the whole pass): $C8EC != 0 (global lock); or $C8EB bit1 (party),
;   bit3 (zone-select), bit7 (battle-view); or bit4 (battle) AND $C8EF==$0F; or
;   bit2 (zone-scroll) with $C969==0 AND $C91E==1 (mid-transition).
; Then walk $D7D2 (32-byte records): byte[0]=$FF end; byte[0] bit6 paused → skip;
;   byte[1]=$FF inactive → skip; else Sub_4D0A builds this object's OAM sprite.
; ============================================================================
Bank6_fn1:  ; $4CBC
    LD A,($C8EC)                           ; $4CBC [FA EC C8]  ; global busy/transition lock
    OR A                                   ; $4CBF [B7]
    RET NZ                                 ; $4CC0 [C0]         ; locked → draw nothing
    LD A,($C8EB)                           ; $4CC1 [FA EB C8]  ; wStateFlags
    BIT 1,A                                ; $4CC4 [CB 4F]      ; party screen?
    RET NZ                                 ; $4CC6 [C0]
    BIT 3,A                                ; $4CC7 [CB 5F]      ; zone-select / mini-map?
    RET NZ                                 ; $4CC9 [C0]
    BIT 7,A                                ; $4CCA [CB 7F]      ; battle view?
    RET NZ                                 ; $4CCC [C0]
    BIT 4,A                                ; $4CCD [CB 67]      ; battle scene?
    JR Z,$4CD7                             ; $4CCF [28 06]
    LD A,($C8EF)                           ; $4CD1 [FA EF C8]  ; battle phase
    CP $0F                                 ; $4CD4 [FE 0F]
    RET Z                                  ; $4CD6 [C8]         ; battle in phase $0F → skip
.lbl_4CD7:
    LD A,($C8EB)                           ; $4CD7 [FA EB C8]  ; wStateFlags
    BIT 2,A                                ; $4CDA [CB 57]      ; zone-scroll transition?
    JR Z,$4CEA                             ; $4CDC [28 0C]      ; not scrolling → render
    LD A,($C969)                           ; $4CDE [FA 69 C9]  ; sub-area? (sub-areas still render)
    OR A                                   ; $4CE1 [B7]
    JR NZ,$4CEA                            ; $4CE2 [20 06]
    LD A,($C91E)                           ; $4CE4 [FA 1E C9]  ; transition phase
    CP $01                                 ; $4CE7 [FE 01]
    RET Z                                  ; $4CE9 [C8]         ; mid zone-scroll → skip this frame
.lbl_4CEA:
    LD DE,$D7D2                            ; $4CEA [11 D2 D7]  ; DE → first object record
.lbl_4CED:
    LD A,(DE)                              ; $4CED [1A]        ; byte[0] = type/flags
    CP $FF                                 ; $4CEE [FE FF]
    RET Z                                  ; $4CF0 [C8]         ; $FF → end of table
    BIT 6,A                                ; $4CF1 [CB 77]
    JR NZ,$4CFF                            ; $4CF3 [20 0A]      ; bit6 paused/hidden → skip (no sprite)
    INC DE                                 ; $4CF5 [13]
    LD A,(DE)                              ; $4CF6 [1A]        ; byte[1] = active flag
    DEC DE                                 ; $4CF7 [1B]
    CP $FF                                 ; $4CF8 [FE FF]
    PUSH DE                                ; $4CFA [D5]
    CALL NZ,$4D0A                          ; $4CFB [C4 0A 4D]  ; active → build this object's OAM sprite
    POP DE                                 ; $4CFE [D1]
.lbl_4CFF:
    LD A,E                                 ; $4CFF [7B]        ; DE += $20 → next 32-byte record
    ADD A,$20                              ; $4D00 [C6 20]
    LD E,A                                 ; $4D02 [5F]
    LD A,D                                 ; $4D03 [7A]
    ADC A,$00                              ; $4D04 [CE 00]
    LD D,A                                 ; $4D06 [57]
    JR,$4CED                               ; $4D07 [18 E4]     ; loop to next object
    RET                                    ; $4D09 [C9]         ; (unreached)
; ----------------------------------------------------------------------------
; Sub_4D0A — build ONE object's OAM sprite.  DE → its 32-byte record in $D7D2.
;   Copies the object's screen position + sprite params from the record into the
;   OAM metasprite param block $FFC3-$FFCA, then hands off to the composer:
;     record +$18/+$19  -> $FFC3/$FFC4  (X, 16-bit)
;     record +$1A/+$1B  -> $FFC5/$FFC6  (Y, 16-bit; +$08 pixel offset)
;     record +$11       -> $FFC7        (sprite tile/frame; written by fn3 tails)
;     record +$14       -> $FFC8   ($FF here = single-part sprite -> done early)
;     record +$16/+$17  -> $FFC9/$FFCA  (2nd-part tile/attr)
;   Then a record flag byte selects the composer: 0 -> bank5 fn0, else bank4 fn2.
; ----------------------------------------------------------------------------
.lbl_4D0A:
    PUSH BC                                ; $4D0A [C5]
    PUSH DE                                ; $4D0B [D5]         ; save record base
    LD A,E                                 ; $4D0C [7B]         ; DE += $18 → record+$18 (position block)
    ADD A,$18                              ; $4D0D [C6 18]
    LD E,A                                 ; $4D0F [5F]
    LD A,D                                 ; $4D10 [7A]
    ADC A,$00                              ; $4D11 [CE 00]
    LD D,A                                 ; $4D13 [57]
    LD HL,$FFC3                            ; $4D14 [21 C3 FF]  ; HL → OAM param block (hXBase)
    LD A,(DE)                              ; $4D17 [1A]        ; +$18 = X lo
    LDI (HL),A                             ; $4D18 [22]         ; → $FFC3
    INC DE                                 ; $4D19 [13]
    LD A,(DE)                              ; $4D1A [1A]        ; +$19 = X hi
    LDI (HL),A                             ; $4D1B [22]         ; → $FFC4
    INC DE                                 ; $4D1C [13]
    LD A,(DE)                              ; $4D1D [1A]        ; +$1A = Y lo
    INC DE                                 ; $4D1E [13]
    ADD A,$08                              ; $4D1F [C6 08]      ; +8 pixel offset
    LDI (HL),A                             ; $4D21 [22]         ; → $FFC5
    LD A,(DE)                              ; $4D22 [1A]        ; +$1B = Y hi
    INC DE                                 ; $4D23 [13]
    ADC A,$00                              ; $4D24 [CE 00]      ; propagate the +8 carry
    LDI (HL),A                             ; $4D26 [22]         ; → $FFC6
    POP DE                                 ; $4D27 [D1]         ; restore record base
    LD A,E                                 ; $4D28 [7B]         ; DE = record+$11 (sprite tile)
    ADD A,$11                              ; $4D29 [C6 11]
    LD E,A                                 ; $4D2B [5F]
    LD A,D                                 ; $4D2C [7A]
    ADC A,$00                              ; $4D2D [CE 00]
    LD D,A                                 ; $4D2F [57]
    LD A,(DE)                              ; $4D30 [1A]        ; +$11 = tile/frame
    LDI (HL),A                             ; $4D31 [22]         ; → $FFC7
    INC DE                                 ; $4D32 [13]         ; skip to record+$14
    INC DE                                 ; $4D33 [13]
    INC DE                                 ; $4D34 [13]
    LD A,(DE)                              ; $4D35 [1A]        ; +$14
    CP $FF                                 ; $4D36 [FE FF]
    JR Z,$4D58                             ; $4D38 [28 1E]      ; $FF → single-part sprite, done
    LDI (HL),A                             ; $4D3A [22]         ; → $FFC8
    INC DE                                 ; $4D3B [13]         ; → record+$16
    INC DE                                 ; $4D3C [13]
    LD A,(DE)                              ; $4D3D [1A]        ; +$16
    LDI (HL),A                             ; $4D3E [22]         ; → $FFC9
    INC DE                                 ; $4D3F [13]
    LD A,(DE)                              ; $4D40 [1A]        ; +$17
    LDI (HL),A                             ; $4D41 [22]         ; → $FFCA
    LD A,E                                 ; $4D42 [7B]        ; DE -= $08 → back to record+$0F
    ADD A,$F8                              ; $4D43 [C6 F8]
    LD E,A                                 ; $4D45 [5F]
    LD A,D                                 ; $4D46 [7A]
    ADC A,$FF                              ; $4D47 [CE FF]
    LD D,A                                 ; $4D49 [57]
    LD A,(DE)                              ; $4D4A [1A]        ; +$0F = composer-select flag
    OR A                                   ; $4D4B [B7]
    JR NZ,$4D54                            ; $4D4C [20 06]
    LD HL,$0500                            ; $4D4E [21 00 05]  ; flag 0 → standard OAM composer
    RST $10                                ; $4D51 [D7]  ; bankcall → bank5 fn0
    JR,$4D58                               ; $4D52 [18 04]
.lbl_4D54:
    LD HL,$0402                            ; $4D54 [21 02 04]  ; flag≠0 → bank4 fn2 (scroll-aware sprite path)
    RST $10                                ; $4D57 [D7]  ; bankcall → bank4 fn2
.lbl_4D58:
    POP BC                                 ; $4D58 [C1]
    RET                                    ; $4D59 [C9]

; ============================================================================
; Bank6_fn4 ($4D5A) — FIELD-OBJECT SPRITE-TILE LOADER
; ----------------------------------------------------------------------------
; Walks the 6-entry secondary object table at WRAM $D7BE (2 bytes/entry:
;   [gfxId, variantFlag]) and LZ-decompresses each object's sprite graphics into
;   a per-object VRAM slot via ROM0 SafeTileLoad ($194A; D=bank,E=block,HL=dest).
;   (This is the graphics-load pass; the 32-byte live objects live at $D7D2.)
; Per entry:
;   * gfxId == $FF               -> end of list, return.
;   * variantFlag == 0           -> {block,bank} = ROM0 GfxTbl $2EAE[gfxId*2]
;                                   (standard NPC sprites; bank $31).
;   * variantFlag != 0           -> {block,bank} = local GfxTbl $4DCC[gfxId*2]
;                                   (special/area sprites; banks $2F/$31).
;   * VRAM dest page = $80 + slotCtr(C) + AREA OFFSET, L=0 (16-tile aligned):
;         sub-area ($C969!=0) +$07 · area $08 +0 · area $45 +$02 · else +$05.
;   * slotCtr C += 1 per entry, +1 more when gfxId is $55/$15 with a zero follow
;     byte (those object types occupy TWO 16-tile VRAM slots).
; Called on scene (re)build — e.g. bank7 party-screen close ($69E1) reloads the
; field sprites this way. Uses SafeTileLoad (HBlank-safe) since the LCD is on.
; ============================================================================
Bank6_fn4:  ; $4D5A
    LD HL,$D7BE                            ; $4D5A [21 BE D7]  ; HL = secondary object table
    LD B,$06                               ; $4D5D [06 06]      ; up to 6 entries
    LD C,$00                               ; $4D5F [0E 00]      ; C = running VRAM slot counter
.lbl_4D61:
    LD A,(HL)                              ; $4D61 [7E]         ; A = gfxId (entry byte 0)
    CP $FF                                 ; $4D62 [FE FF]
    RET Z                                  ; $4D64 [C8]         ; $FF -> end of list
    PUSH HL                                ; $4D65 [E5]         ; save entry ptr + loop regs
    PUSH BC                                ; $4D66 [C5]
    LD B,A                                 ; $4D67 [47]         ; B = gfxId (table index)
    INC HL                                 ; $4D68 [23]
    LD A,(HL)                              ; $4D69 [7E]         ; A = variantFlag (entry byte 1)
    OR A                                   ; $4D6A [B7]
    JR NZ,$4D7A                            ; $4D6B [20 0D]      ; variant!=0 -> local GfxTbl
    ; --- variantFlag == 0: descriptor from ROM0 GfxTbl $2EAE[gfxId*2] ---
    LD HL,$2EAE                            ; $4D6D [21 AE 2E]  ; ROM0 sprite-descriptor table
    LD A,B                                 ; $4D70 [78]
    ADD A,A                                ; $4D71 [87]         ; gfxId*2 (word entries)
    ADD A,L                                ; $4D72 [85]
    LD L,A                                 ; $4D73 [6F]
    LD A,$00                               ; $4D74 [3E 00]
    ADC A,H                                ; $4D76 [8C]
    LD H,A                                 ; $4D77 [67]         ; HL = &GfxTbl[gfxId]
    JR,$4D86                               ; $4D78 [18 0C]
.lbl_4D7A:
    ; --- variantFlag != 0: descriptor from local GfxTbl $4DCC[gfxId*2] ---
    LD L,B                                 ; $4D7A [68]
    LD H,$00                               ; $4D7B [26 00]
    ADD HL,HL                              ; $4D7D [29]         ; gfxId*2
    LD A,L                                 ; $4D7E [7D]
    ADD A,$CC                              ; $4D7F [C6 CC]      ; + $4DCC (local table base)
    LD L,A                                 ; $4D81 [6F]
    LD A,H                                 ; $4D82 [7C]
    ADC A,$4D                              ; $4D83 [CE 4D]
    LD H,A                                 ; $4D85 [67]         ; HL = &Bank6_ObjGfxTbl[gfxId]
.lbl_4D86:
    LD E,(HL)                              ; $4D86 [5E]         ; E = block (SafeTileLoad fn index)
    INC HL                                 ; $4D87 [23]
    LD D,(HL)                              ; $4D88 [56]         ; D = ROM bank -> DE = {bank,block}
    LD A,C                                 ; $4D89 [79]         ; --- compute VRAM dest page ---
    ADD A,$80                              ; $4D8A [C6 80]      ; base page $80 + slotCtr
    LD H,A                                 ; $4D8C [67]
    LD A,($C969)                           ; $4D8D [FA 69 C9]  ; wSubAreaFlag
    OR A                                   ; $4D90 [B7]
    JR Z,$4D99                             ; $4D91 [28 06]      ; not sub-area -> per-area offset
    LD A,H                                 ; $4D93 [7C]
    ADD A,$07                              ; $4D94 [C6 07]      ; sub-area: page += $07
    LD H,A                                 ; $4D96 [67]
    JR,$4DAE                               ; $4D97 [18 15]
.lbl_4D99:
