; Collision / interaction scan:
;   Reads WRAM[$CAC0] (player object index?) and uses ROM0 $260A to
;   index WRAM[$CB0C] (object coordinate table). Then iterates via
;   $50D2 comparing positions — likely spatial overlap or proximity
;   detection between the player and other field objects (trigger zones,
;   NPCs, warp tiles).
