; ============================================================================
; Bank6_fn6  ($6034)  — OVERWORLD GUI STATE DISPATCHER  (per-frame master router)
; ============================================================================
; THE most important routine in the field state: called once per frame, it
; decides WHICH screen/mode owns this frame and runs it. Everything the player
; sees while "in the game world" — walking, talking, menus, shops, scrolling,
; sub-screens — is dispatched from here. Invoked as bank6/fn6 (HL=$0B06;RST$10)
; from the state machine each frame.
;
; ── CONTROL-FLOW MAP (5 phases) ─────────────────────────────────────────────
;   PHASE 0  $6034  LOCK GATE       : if $C88F != 0 (transition/fade) -> RET now.
;   PHASE 1  $6039  MODE ROUTER     : if any $C8EB mode bit set -> that handler.
;   PHASE 2  $606B  DEFAULT FIELD   : no mode bit -> normal overworld: busy
;                                     gates, Start=menu, Select=area-warp.
;   PHASE 3  $611D  INTERACTION     : A pressed -> probe faced cell (bank11 fn4)
;                                     -> event/dialogue (bank4 fn5).
;   PHASE 4  $61E9  STEP / MOVE     : nothing faced -> sub-area edge probe.
;   PHASE 5  $6247  TAIL            : A w/o target -> open party screen; $6284=RET.
;
; ── PHASE 1: $C8EB MODE BITS (checked 5,7,4,0,1,3,6,2 — FIRST set bit wins) ──
;     bit5 -> $6B86      INDOOR/FACILITY area entry+display overlay (24-state $C905
;                        build sequence). SET by bank11 when routing into special
;                        areas ($53,$54-$59,$61-$64) & on sub-area exit ($466E/$46CF);
;                        facility logic delegated to bank22 fn8. Self-clears at
;                        $6D97/$6E4B. ("shop/menu" was an imprecise earlier guess.)
;     bit7 -> $6295      bank9 fn1 (BattleView; swaps scroll state via Sub_62A0).
;                        earlier "dialog" label unconfirmed; setter not in disasm.
;     bit4 -> $62B2      bank9 fn0 = BATTLE SCENE / animation (dispatch $C8EF).
;                        SET by bank81 battle-init $6805 (with $C8EF=$FF,$C905=0).
;     bit0 -> $67A9      screen scroll driver (low-level per-pixel BG scroll)
;     bit1 -> bank7 fn0  info / party screen (press A on empty tile; see bank7)
;     bit3 -> bank25 fn0 SELECT mini-map / zone selector (areas $50-$5C; SET $60EA)
;     bit6 -> bank19 fn3 BG-row/strip scroll-repaint animation (3 phases on $C905).
;                        Transiently raised by the scroll-transition orchestrator
;                        ($6A01 → $6AD6) at scroll sub-phase $C917==$17, with params
;                        from $CAB4-indexed table $6B0B stored to $DA03/$DA04.
;     bit2 -> $62F6      inter-zone SCREEN-SCROLL transition (dir=$C91D, see .lbl_62F6)
;   Overworld-navigation pair: bit3 (pick a zone on the map) + bit2 (scroll-animate
;   the move, $C500->$C300 double-buffer). bit4/bit7 are the BATTLE overlay (bank9),
;   a different family that just shares this same fn6 scheduler + $C8EB byte.
;   (Set/cleared by the handlers themselves + bank1/bank11; see wStateFlags in
;    wram.asm for the full bit map. A set bit = "an overlay owns the frame".)
;
; ── PHASE 2/3 DECISION TREE (no mode bit set) ───────────────────────────────
;   busy? ($D9E8 script | $D8D7 move | $C8A8 | $FF90.0 warp)   -> PHASE 5 tail
;   $C8AA sub-mode set                                          -> PHASE 3 ($611D)
;   $C850 animation                                             -> PHASE 3
;   Start pressed ($C846 bit3)                                  -> toggle+menu prep
;   Select pressed ($C846 bit2) on a warp area ($50-$5C etc.)   -> start scroll xition
;   else                                                        -> PHASE 3
;   PHASE 3: A pressed ($C846 bit0)? no -> PHASE 5. yes -> probe OWN cell
;     (bank11 fn4 @$614B); if empty, probe cell AHEAD ($FF8E facing via delta
;     table $6285, @$6183). HIT ($FFD5!=$FF) -> $618E hand-off: $D8D4=event id,
;     $D8D3=wAreaType($70 if sub-area), mark object rec bit6, run bank4/fn5
;     (event/dialogue VM); if it triggers a move ($D8D7 bit1) -> SET $C8EB.0.
;
; ── KEY STATE READ ──────────────────────────────────────────────────────────
;   $C88F lock · $C8EB mode bits · $C846 joypad (bit0=A,bit2=Select,bit3=Start)
;   $C850 anim · $D8D7 move-flags · $C968/$C969 area/sub-area · $FF8E facing.
; See also: wStateFlags/$C8EB and wFieldLock/$C88F (wram.asm), bank11 fn4
; (faced-object scan), bank4 fn5 (event VM). Jump-target blocks are labelled
; with their own headers just below (.lbl_6B86 / _67A9 / _6295 / _62B2 / etc.).
; ============================================================================
Bank6_fn6:  ; $6034
    LD A,($C88F)                           ; $6034 [FA 8F C8]  ; WRAM[$C88F]
    OR A                                   ; $6037 [B7]  ; test $C88F (field lock)
    RET NZ                                 ; $6038 [C0]  ; locked ($C88F!=0) -> abort; field frozen this frame
    ; route on the active-mode bit in WRAM[$C8EB] (first set bit wins):
    ; == PHASE 1: MODE ROUTER — first set $C8EB bit wins (order 5,7,4,0,1,3,6,2) ==
    LD A,($C8EB)                           ; $6039 [FA EB C8]  ; field mode flags
    BIT 5,A                                ; $603C [CB 6F]  ; $C8EB bit5?
    JP NZ,$6B86                            ; $603E [C2 86 6B]  ; bit5 → shop/menu overlay ($6B86)
    BIT 7,A                                ; $6041 [CB 7F]  ; $C8EB bit7?
    JP NZ,$6295                            ; $6043 [C2 95 62]  ; bit7 → $6295 → bank9 fn1 (BattleView; "dialog" unconfirmed)
    BIT 4,A                                ; $6046 [CB 67]  ; $C8EB bit4?
    JP NZ,$62B2                            ; $6048 [C2 B2 62]  ; bit4 → $62B2 → bank9 fn0 = BATTLE scene (set by bank81)
    BIT 0,A                                ; $604B [CB 47]  ; $C8EB bit0?
    JP NZ,$67A9                            ; $604D [C2 A9 67]  ; bit0 → screen scroll ($67A9)
    BIT 1,A                                ; $6050 [CB 4F]  ; $C8EB bit1?
    JR Z,$6059                             ; $6052 [28 05]  ; bit1 clear -> next check
    LD HL,$0700                            ; $6054 [21 00 07]  ; bank7 fn0 ...
    RST $10                                ; $6057 [D7]  ; bit1 → bankcall → bank7 fn0 (info screen)
    RET                                    ; $6058 [C9]  ; (bit1 done)
.lbl_6059:
    BIT 3,A                                ; $6059 [CB 5F]  ; $C8EB bit3?
    JR Z,$6062                             ; $605B [28 05]  ; bit3 clear -> next
    LD HL,$1900                            ; $605D [21 00 19]  ; bank25 fn0 ...
    RST $10                                ; $6060 [D7]  ; bit3 → bankcall → bank25 fn0
    RET                                    ; $6061 [C9]  ; (bit3 done)
.lbl_6062:
    BIT 6,A                                ; $6062 [CB 77]  ; $C8EB bit6?
    JR Z,$606B                             ; $6064 [28 05]  ; bit6 clear -> default field path
    LD HL,$1303                            ; $6066 [21 03 13]  ; bank19 fn3 ...
    RST $10                                ; $6069 [D7]  ; bit6 → bankcall → bank19 fn3
    RET                                    ; $606A [C9]  ; (bit6 done)
; no overlay/mode bit set → normal overworld: gate on many "busy" flags,
;   and only then poll the joypad to (maybe) open the main menu.
.lbl_606B:
    ; == PHASE 2: DEFAULT FIELD (no $C8EB mode bit set) — normal overworld ==
    BIT 2,A                                ; $606B [CB 57]  ; $C8EB bit2?
    JP NZ,$62F6                            ; $606D [C2 F6 62]  ; bit2 → inter-zone SCREEN-SCROLL transition ($62F6)
    LD A,($D9E8)                           ; $6070 [FA E8 D9]  ; script/event busy?
    OR A                                   ; $6073 [B7]  ; busy? -> object updates only
    JP NZ,$6284                            ; $6074 [C2 84 62]  ; → just run object updates
    LD A,($D8D7)                           ; $6077 [FA D7 D8]  ; player move in progress?
    OR A                                   ; $607A [B7]  ; busy?
    JP NZ,$6284                            ; $607B [C2 84 62]  ; busy -> object updates only
    LD A,($C8A8)                           ; $607E [FA A8 C8]  ; another busy flag?
    OR A                                   ; $6081 [B7]  ; busy?
