.lbl_61E9:
    LD A,($C969)                           ; $61E9 [FA 69 C9]  ; WRAM[$C969]
    OR A                                   ; $61EC [B7]
    JP Z,$6247                             ; $61ED [CA 47 62]
    LD HL,$6285                            ; $61F0 [21 85 62]
