    LDH A,($FF95)                          ; $6211 [F0 95]  ; HRAM[$FF95]
    LD L,A                                 ; $6213 [6F]
    LDH A,($FF96)                          ; $6214 [F0 96]  ; HRAM[$FF96]
    LD H,A                                 ; $6216 [67]
    ADD HL,DE                              ; $6217 [19]
    LD A,L                                 ; $6218 [7D]
    LDH ($FFDD),A                          ; $6219 [E0 DD]  ; → HRAM[$FFDD]
    LD A,H                                 ; $621B [7C]
    LDH ($FFDE),A                          ; $621C [E0 DE]  ; → HRAM[$FFDE]
    LDH A,($FFDB)                          ; $621E [F0 DB]  ; HRAM[$FFDB]
