    LDH ($FFDB),A                          ; $622C [E0 DB]  ; → HRAM[$FFDB]
    LDH A,($FFDD)                          ; $622E [F0 DD]  ; HRAM[$FFDD]
    SWAP A                                 ; $6230 [CB 37]
