; .lbl_6247 — post-interaction tail: A-press with NO target -> open info/party.
;   Returns ($6284) if busy ($D8D7 / any $C8EB mode / $C850 anim). Otherwise, if
;   A is pressed ($C846 bit0) and a party exists ($CA8D!=0): SET $C8EB bit1
;   (info/party screen), clear $C90D-$C910, play SFX $59.
; ----------------------------------------------------------------------------
.lbl_6247:
    LD A,($D8D7)                           ; $6247 [FA D7 D8]  ; WRAM[$D8D7]
    OR A                                   ; $624A [B7]
    JP NZ,$6284                            ; $624B [C2 84 62]
    LD A,($C8EB)                           ; $624E [FA EB C8]  ; WRAM[$C8EB]
    OR A                                   ; $6251 [B7]
    JP NZ,$6284                            ; $6252 [C2 84 62]
    LD A,($C850)                           ; $6255 [FA 50 C8]  ; WRAM[$C850]
    OR A                                   ; $6258 [B7]
    JP NZ,$6284                            ; $6259 [C2 84 62]
    LD A,($C846)                           ; $625C [FA 46 C8]  ; WRAM[$C846]
    AND $01                                ; $625F [E6 01]
    JR Z,$6284                             ; $6261 [28 21]
    LD A,($CA8D)                           ; $6263 [FA 8D CA]  ; WRAM[$CA8D]
    OR A                                   ; $6266 [B7]
    JR Z,$6284                             ; $6267 [28 1B]
    LD HL,$C8EB                            ; $6269 [21 EB C8]
    SET 1,(HL)                             ; $626C [CB CE]
