    LD ($C90E),A                           ; $6272 [EA 0E C9]  ; → WRAM[$C90E]
    XOR A                                  ; $6275 [AF]
    LD ($C90F),A                           ; $6276 [EA 0F C9]  ; → WRAM[$C90F]
    LD ($C910),A                           ; $6279 [EA 10 C9]  ; → WRAM[$C910]
    LD A,$59                               ; $627C [3E 59]
    CALL $1EFF                             ; $627E [CD FF 1E]  ; ROM0 $1EFF
    JP $6284                               ; $6281 [C3 84 62]
; ----------------------------------------------------------------------------
; .lbl_6284 — shared RET (fn6's do-nothing / busy-exit return).
; ----------------------------------------------------------------------------
.lbl_6284:
    RET                                    ; $6284 [C9]
; ----------------------------------------------------------------------------
; DATA: facing-direction DELTA table ($6285, 16 bytes = 4 dirs x {dX:dw, dY:dw}),
;   indexed by facing dir $FF8E (hScrollDir). fn6 ($6155 / $61F0) uses it to find
;   the cell in front of the player. The bytes below decode as NOP/instructions
;   but are DATA, not code.
; ----------------------------------------------------------------------------
    NOP                                    ; $6285 [00]
    NOP                                    ; $6286 [00]
    STOP                                   ; $6287 [10 00]
    LDH A,($FFFF)                          ; $6289 [F0 FF]  ; HRAM[$FFFF]
    NOP                                    ; $628B [00]
    NOP                                    ; $628C [00]
    NOP                                    ; $628D [00]
    NOP                                    ; $628E [00]
    LDH A,($FFFF)                          ; $628F [F0 FF]  ; HRAM[$FFFF]
    STOP                                   ; $6291 [10 00]
    NOP                                    ; $6293 [00]
    NOP                                    ; $6294 [00]
; ----------------------------------------------------------------------------
; .lbl_6295 — $C8EB bit7 handler: DIALOG / scripted-event mode.
;   Sub $62A0, then bank9 fn1 (HL=$0901) — advances the active message/event.
; ----------------------------------------------------------------------------
.lbl_6295:
    CALL $62A0                             ; $6295 [CD A0 62]
    LD HL,$0901                            ; $6298 [21 01 09]
    RST $10                                ; $629B [D7]  ; bankcall → bank9 fn1
    CALL $62A0                             ; $629C [CD A0 62]
    RET                                    ; $629F [C9]
.lbl_62A0:
    LD HL,$C905                            ; $62A0 [21 05 C9]
    LD DE,$C876                            ; $62A3 [11 76 C8]
    LD B,$08                               ; $62A6 [06 08]
.lbl_62A8:
    LD C,(HL)                              ; $62A8 [4E]
    LD A,(DE)                              ; $62A9 [1A]
    LDI (HL),A                             ; $62AA [22]
    LD A,C                                 ; $62AB [79]
    LD (DE),A                              ; $62AC [12]
    INC DE                                 ; $62AD [13]
    DEC B                                  ; $62AE [05]
    JR NZ,$62A8                            ; $62AF [20 F7]
