; ============================================================================
; .lbl_62F6 — $C8EB bit2 handler: INTER-ZONE SCREEN-SCROLL TRANSITION
; ============================================================================
; NOT a text menu (the earlier "menu-in-progress" label was wrong). This is the
; state machine that scrolls the view from one 4x4-grid zone to an adjacent one
; when the player crosses a zone edge. TWO-LEVEL RST$00 dispatch:
;
;   LEVEL 1  ($62F6) on $C91D = SCROLL DIRECTION (wCursorQuadrant):
;     0 -> $6302  LEFT  (DEC wScrollCount $C925)
;     1 -> $6446  RIGHT (INC $C925)
;     2 -> $651B  UP    (SUB 4 $C925)     [grid is 4 zones wide]
;     3 -> $65EA  DOWN  (ADD 4 $C925)
;
;   LEVEL 2 (each of the above) on $C91E = TRANSITION PHASE (0-4):
;     0  direction-specific: adjust $C925, build the NEW room's tilemap into
;        $C500 via bank11/fn3 (HL=$0B03), set step counter $C91F=$13, INC $C91E.
;     1  $66B8   (shared step)      2  $66C7   (shared step)
;     3  direction-specific (per-dir table entry)
;     4  $63D7   FINISH: copy $C500 -> $C300 (512B live tilemap), RES $C8EB bit2
;        (transition complete), CALL $66F0.
;
; So bit2 orchestrates the zone change + double-buffer swap; the low-level pixel
; scroll is $C8EB bit0 ($67A9). ($C91D/$C91E/$C91F are reused by bank1 as cursor
; state — see wram.asm wCursorQuadrant/$C91E.)
; ============================================================================
.lbl_62F6:
    LD A,($C91D)                           ; $62F6 [FA 1D C9]  ; scroll DIRECTION (0=L,1=R,2=U,3=D)
    RST $00                                ; $62F9 [C7]  ; level-1 dispatch on direction
    ; RST $00 table (4 directions):
    DW $6302    ; $62FA [02 63]  dir 0 = LEFT  (DEC $C925)
    DW $6446    ; $62FC [46 64]  dir 1 = RIGHT (INC $C925)
    DW $651B    ; $62FE [1B 65]  dir 2 = UP    (SUB 4 $C925)
    DW $65EA    ; $6300 [EA 65]  dir 3 = DOWN  (ADD 4 $C925)
.lbl_6302:
    LD A,($C91E)                           ; $6302 [FA 1E C9]  ; $C91E phase index (0-4)
    RST $00                                ; $6305 [C7]  ; state dispatch (A=index, DW table follows)
    ; RST $00 table (5 states):
    DW $6310    ; $6306 [10 63]  phase0: adjust $C925 + build new room tilemap -> $C500 (bank11 fn3), $C91F=$13
    DW $66B8    ; $6308 [B8 66]  phase1: rebuild NPC/object table for new room (bank11 fn7) [$66B8]
    DW $66C7    ; $630A [C7 66]  phase2: advance; queue zone-entry event $D8D4/$D8D3 [$66C7]
    DW $6328    ; $630C [28 63]  phase3: paint the scrolled-in tile column -> VRAM $9800
    DW $63D7    ; $630E [D7 63]  phase4: FINISH -> copy $C500->$C300 (512B), RES $C8EB bit2 [$63D7]
.lbl_6310:
    LD A,($C925)                           ; $6310 [FA 25 C9]  ; WRAM[$C925]
    DEC A                                  ; $6313 [3D]  ; wScrollCount - 1 = LEFT neighbour zone
    LD ($C925),A                           ; $6314 [EA 25 C9]  ; → WRAM[$C925]
    CALL $66E5                             ; $6317 [CD E5 66]  ; $66E5: aim the tilemap build at the off-screen BG map ($9C00)
    LD HL,$0B03                            ; $631A [21 03 0B]  ; bank11 fn3 ...
    RST $10                                ; $631D [D7]  ; bankcall → bank11 fn3
    LD A,$13                               ; $631E [3E 13]  ; A=$13 (19) = per-column step budget
    LD ($C91F),A                           ; $6320 [EA 1F C9]  ; → WRAM[$C91F]
    LD HL,$C91E                            ; $6323 [21 1E C9]  ; advance phase ...
    INC (HL)                               ; $6326 [34]  ; $C91E -> phase 1
    RET                                    ; $6327 [C9]  ; done (one frame)
.lbl_6328:
    LDH A,($FFBB)                          ; $6328 [F0 BB]  ; HRAM[$FFBB]
    AND $F8                                ; $632A [E6 F8]  ; snap camera Y to 8px tile
    LD L,A                                 ; $632C [6F]  ; L = Y
    XOR A                                  ; $632D [AF]  ; A=0
    SLA L                                  ; $632E [CB 25]  ; L<<1 ...
    RLA                                    ; $6330 [17]  ; ...->A (carry)
    SLA L                                  ; $6331 [CB 25]  ; L<<1 ...
    RLA                                    ; $6333 [17]  ; ...->A  (A:L = Y*4 = row*$20)
    LD H,$98                               ; $6334 [26 98]  ; H=$98 (BG map $9800 base)
    ADD A,H                                ; $6336 [84]  ; + row hi
    LD H,A                                 ; $6337 [67]  ; H
    LDH A,($FFB7)                          ; $6338 [F0 B7]  ; HRAM[$FFB7]
    RRCA                                   ; $633A [0F]  ; camera X /8 ...
    RRCA                                   ; $633B [0F]  ; 
    RRCA                                   ; $633C [0F]  ; 
    DEC A                                  ; $633D [3D]  ; -1 (the column just entered on the LEFT)
    AND $1F                                ; $633E [E6 1F]  ; col & $1F (wrap 32)
    ADD A,L                                ; $6340 [85]  ; + row
    LD L,A                                 ; $6341 [6F]  ; L
    LD A,$00                               ; $6342 [3E 00]  ; 
    ADC A,H                                ; $6344 [8C]  ; 
    LD H,A                                 ; $6345 [67]  ; HL = $9800 dest column
    LD A,L                                 ; $6346 [7D]  ; (save dest lo) ...
    LD ($C740),A                           ; $6347 [EA 40 C7]  ; → WRAM[$C740]
    LD A,H                                 ; $634A [7C]  ; (save dest hi)
    LD ($C741),A                           ; $634B [EA 41 C7]  ; → WRAM[$C741]
    LD A,($C91F)                           ; $634E [FA 1F C9]  ; WRAM[$C91F]
    LD DE,$C500                            ; $6351 [11 00 C5]  ; DE = $C500 (new room's tile buffer)
    ADD A,E                                ; $6354 [83]  ; + column offset ...
    LD E,A                                 ; $6355 [5F]  ; 
    LD A,$00                               ; $6356 [3E 00]  ; 
    ADC A,D                                ; $6358 [8A]  ; 
    LD D,A                                 ; $6359 [57]  ; DE -> source column in $C500
    LD A,$01                               ; $635A [3E 01]  ; A=1
    LD ($C742),A                           ; $635C [EA 42 C7]  ; → WRAM[$C742]
    LD A,$10                               ; $635F [3E 10]  ; A=$10 (16 rows)
    LD ($C743),A                           ; $6361 [EA 43 C7]  ; → WRAM[$C743]
    LD HL,$C744                            ; $6364 [21 44 C7]  ; HL = $C744 (VRAM-DMA staging: tiles)
    LD B,$10                               ; $6367 [06 10]  ; B=$10 rows
