    LDH A,($FFB7)                          ; $63B4 [F0 B7]  ; HRAM[$FFB7]
    LD L,A                                 ; $63B6 [6F]  ; L
    LDH A,($FFB8)                          ; $63B7 [F0 B8]  ; HRAM[$FFB8]
    LD H,A                                 ; $63B9 [67]  ; H
    LD A,L                                 ; $63BA [7D]  ; HL -= 8 (advance dest to prev column) ...
    ADD A,$F8                              ; $63BB [C6 F8]  ; 
