    LD A,($C91F)                           ; $63C8 [FA 1F C9]  ; WRAM[$C91F]
    DEC A                                  ; $63CB [3D]  ; dec column budget $C91F
    LD ($C91F),A                           ; $63CC [EA 1F C9]  ; → WRAM[$C91F]
    CP $FF                                 ; $63CF [FE FF]  ; budget hit $FF (all columns done)?
