    LD L,A                                 ; $63FD [6F]  ; 
    LD A,H                                 ; $63FE [7C]  ; 
    ADC A,$C9                              ; $63FF [CE C9]  ; 
    LD H,A                                 ; $6401 [67]  ; HL
    LDH A,($FF92)                          ; $6402 [F0 92]  ; HRAM[$FF92]
    LDI (HL),A                             ; $6404 [22]  ; copy ...
