; ----------------------------------------------------------------------------
; Sub_6AD6 — START the bit6 strip-scroll animation (called from $6A20 at scroll
;   sub-phase $C917==$17). Ends the low-level pixel scroll (RES bit0), selects an
;   animation-parameter word from AnimParamTbl ($6B0B) using $CAB4 as index, and
;   arms bank19 fn3 by setting bit6 + $C905=0.
; ----------------------------------------------------------------------------
.lbl_6AD6:
    LD HL,$C8EB                            ; $6AD6 [21 EB C8]  ; wStateFlags
    RES 0,(HL)                             ; $6AD9 [CB 86]      ; stop bit0 pixel-scroll
    XOR A                                  ; $6ADB [AF]
    LD ($C915),A                           ; $6ADC [EA 15 C9]  ; clear scroll phase ctr
    LD ($C916),A                           ; $6ADF [EA 16 C9]
    LD A,($CAB4)                           ; $6AE2 [FA B4 CA]  ; animation selector index
    ADD A,A                                ; $6AE5 [87]         ; *2 (word table)
    LD HL,$6B0B                            ; $6AE6 [21 0B 6B]  ; AnimParamTbl base
    ADD A,L                                ; $6AE9 [85]
    LD L,A                                 ; $6AEA [6F]
    LD A,$00                               ; $6AEB [3E 00]
    ADC A,H                                ; $6AED [8C]
    LD H,A                                 ; $6AEE [67]         ; HL = &AnimParamTbl[$CAB4]
    LDI A,(HL)                             ; $6AEF [2A]
    LD ($DA03),A                           ; $6AF0 [EA 03 DA]  ; param lo -> $DA03
    LD A,(HL)                              ; $6AF3 [7E]
    LD ($DA04),A                           ; $6AF4 [EA 04 DA]  ; param hi -> $DA04
    LD A,$00                               ; $6AF7 [3E 00]
    LD ($DA02),A                           ; $6AF9 [EA 02 DA]
    LD HL,$C8EB                            ; $6AFC [21 EB C8]  ; --- arm the bit6 animation ---
    SET 6,(HL)                             ; $6AFF [CB F6]      ; $C8EB bit6 = 1 -> fn6 runs bank19 fn3
    XOR A                                  ; $6B01 [AF]
    LD ($C905),A                           ; $6B02 [EA 05 C9]  ; phase 0
    LD A,$00                               ; $6B05 [3E 00]
    LD ($DA09),A                           ; $6B07 [EA 09 DA]
    RET                                    ; $6B0A [C9]
