; ----------------------------------------------------------------------------
; .lbl_6B86 — $C8EB bit5 handler: INDOOR / FACILITY AREA ENTRY + DISPLAY overlay.
;   Highest-priority mode bit (checked 1st in fn6). A 24-state build/teardown
;   sequence keyed on $C905 that fades/constructs an indoor area or facility
;   interior after bank11 routes you into one (areas $53,$54-$59,$61-$64) or on
;   sub-area exit. Facility-specific logic runs in bank22 fn8. Self-clears bit5
;   at $6D97 / $6E4B when the sequence finishes.
;   ENTRY: pick the variant — sub-area ($C969!=0) or "big" area ($C968>=$50 except
;   $52/$60) start at state $10; everything else starts at state 0.
; ----------------------------------------------------------------------------
.lbl_6B86:
    LD A,($C905)                           ; $6B86 [FA 05 C9]  ; sub-phase; if !=0 resume ($6BA6)
    OR A                                   ; $6B89 [B7]
    JR NZ,$6BA6                            ; $6B8A [20 1A]      ; already running -> dispatch
    LD A,($C969)                           ; $6B8C [FA 69 C9]  ; wSubAreaFlag: sub-area?
    OR A                                   ; $6B8F [B7]
    JR NZ,$6BA1                            ; $6B90 [20 0F]      ; sub-area -> start at state $10
    LD A,($C968)                           ; $6B92 [FA 68 C9]  ; wAreaID
    CP $50                                 ; $6B95 [FE 50]
    JR C,$6BA6                             ; $6B97 [38 0D]      ; area <$50 -> state 0 (small/outdoor)
    CP $52                                 ; $6B99 [FE 52]
    JR Z,$6BA6                             ; $6B9B [28 09]      ; area $52 -> state 0
    CP $60                                 ; $6B9D [FE 60]
    JR Z,$6BA6                             ; $6B9F [28 05]      ; area $60 -> state 0
.lbl_6BA1:
    LD A,$10                               ; $6BA1 [3E 10]     ; big/indoor area or sub-area:
    LD ($C905),A                           ; $6BA3 [EA 05 C9]  ; start at state $10 (alt build path)
